export function translate(text,lang){if(lang==='mn')return text;if(['es','id','ja'].includes(lang)){const english=translate(text,'en');return EXTRA[lang][english.trim()] ? english.replace(english.trim(),EXTRA[lang][english.trim()]) : localizeDynamic(english,lang);}const trimmed=text.trim();if(EN[trimmed])return text.replace(trimmed,EN[trimmed]);const substitutions=[[/^АРЫН КАМЕР/,'REAR CAMERA'],[/^УРД КАМЕР/,'FRONT CAMERA'],[/^КАМЕР ·/,'CAMERA ·'],[/^Тэмдэглэсэн асуулт:/,'Marked question:'],[/^Сонсож байна · (\d+) сек үлдлээ$/,'Recording · $1 seconds remaining'],[/^Загвар татаж байна…/,'Downloading model…'],[/^Суурь хэмжилт бэлэн ·/,'Baseline ready ·']];for(const [pattern,replacement] of substitutions)if(pattern.test(trimmed))return text.replace(trimmed,trimmed.replace(pattern,replacement));return text}
export function initLanguage(){const selector=document.getElementById('appLang'),dialog=document.getElementById('languageDialog');if(!selector)return;let lang='mn',saved=null;try{saved=localStorage.getItem('ghost-lens-ui-language')}catch{}if(['mn','en','es','id','ja'].includes(saved))lang=saved;else saved=null;const originals=new WeakMap(),attributes=new WeakMap();
function skip(node){const e=node.parentElement;if(!e)return true;if(e.closest('script,style,pre,[data-no-translate],#soundTitle,#speechInterim,#questionStatus'))return true;const data=e.closest('#soundHistory,#events,#history');return !!data&&!e.closest('button,.empty');}
function update(node){if(node.nodeType===3){if(skip(node))return;const old=originals.get(node);let source=node.nodeValue;if(old&&source===old.shown)source=old.source;const shown=translate(source,lang);originals.set(node,{source,shown});if(node.nodeValue!==shown)node.nodeValue=shown;return}if(node.nodeType!==1)return;for(const attr of ['placeholder','aria-label']){if(!node.hasAttribute(attr))continue;let originalsForNode=attributes.get(node);if(!originalsForNode){originalsForNode={};attributes.set(node,originalsForNode)}if(!(attr in originalsForNode))originalsForNode[attr]=node.getAttribute(attr);const next=translate(originalsForNode[attr],lang);if(node.getAttribute(attr)!==next)node.setAttribute(attr,next)}for(const child of Array.from(node.childNodes))update(child)}
function apply(value,remember){lang=['mn','en','es','id','ja'].includes(value)?value:'mn';selector.value=lang;document.documentElement.lang=lang;document.title=lang==='ja'?'Ghost Lens・ライブ測定':lang==='mn'?'Ghost Lens • Шууд лаборатори':'Ghost Lens • Live lab';if(remember)try{localStorage.setItem('ghost-lens-ui-language',lang)}catch{}update(document.body)}
const observer=new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')update(record.target);else for(const node of record.addedNodes)update(node)}});observer.observe(document.body,{subtree:true,childList:true,characterData:true});selector.onchange=()=>apply(selector.value,true);for(const [id,value]of [['chooseMn','mn'],['chooseEn','en'],['chooseEs','es'],['chooseId','id'],['chooseJa','ja']]){const button=document.getElementById(id);if(button)button.onclick=()=>{apply(value,true);if(dialog?.open)dialog.close();else if(dialog)dialog.hidden=true;selector.focus()}}apply(lang,false);if(dialog&&!saved){dialog.hidden=false;if(typeof dialog.showModal==='function')dialog.showModal();else dialog.classList.add('language-fallback')}return {getLanguage:()=>lang,setLanguage:value=>apply(value,true)};}

