for(const [language,rows] of Object.entries(localeRows)){if(rows.length!==Object.values(EN).length)throw Error("Locale catalog length mismatch: "+language);Object.values(EN).forEach((english,i)=>EXTRA[language][english]=rows[i]);}

function localizeDynamic(text,language){const labels={es:['CÁMARA TRASERA','CÁMARA FRONTAL','CÁMARA','Pregunta marcada:','Grabando · $1 segundos restantes','Descargando modelo…','Referencia lista ·'],id:['KAMERA BELAKANG','KAMERA DEPAN','KAMERA','Pertanyaan ditandai:','Merekam · tersisa $1 detik','Mengunduh model…','Acuan siap ·'],ja:['背面カメラ','前面カメラ','カメラ','指定した質問:','録音中 · 残り$1秒','モデルをダウンロード中…','基準値の測定完了 ·']}[language];if(!labels)return text;const patterns=[/^REAR CAMERA/,/^FRONT CAMERA/,/^CAMERA ·/,/^Marked question:/,/^Recording · (\d+) seconds remaining$/,/^Downloading model…/,/^Baseline ready ·/];for(let i=0;i<patterns.length;i++)if(patterns[i].test(text))return text.replace(patterns[i],labels[i]);return text;}
